function(container, apiUrl, tables) {
  const facilitiesTableIndex = 0;
  const timeSlotsTableIndex = 1;
  const bookingsTableIndex = 2;
  const categoriesTableIndex = 3;

  let selectedFacilityId = null;
  let selectedDate = null;
  let selectedTimeSlot = null;
  let currentAction = null; // 'book' or 'lottery'

  // Initialize
  async function init() {
    await loadFacilities();
    await loadBookings();
    attachEventListeners();
  }

  // Load facilities
  async function loadFacilities() {
    const facilities = await window.aivicApi.list(facilitiesTableIndex);
    if (!facilities) return;

    const searchInput = container.querySelector('[data-testid="facility-search-input"]');
    const categoryFilter = container.querySelector('[data-testid="category-filter-select"]');
    const dateInput = container.querySelector('[data-testid="facility-date-input"]');

    const renderFacilities = () => {
      const searchTerm = searchInput.value.toLowerCase();
      const selectedCategory = categoryFilter.value;
      const filtered = facilities.filter(f => {
        const matchesSearch = f.施設名.toLowerCase().includes(searchTerm);
        const matchesCategory = !selectedCategory || f.カテゴリ === selectedCategory;
        return matchesSearch && matchesCategory;
      });

      const listContainer = container.querySelector('#facilities-list');
      listContainer.innerHTML = filtered.map(facility => `
        <div class="card" data-id="${facility.施設ID}" style="padding: 16px; cursor: pointer; transition: background 200ms; border-radius: var(--radius-card); background: var(--bg-card); border: 1px solid var(--border);" 
          onmouseover="this.style.background='var(--sidebar-item-hover)'"
          onmouseout="this.style.background='var(--bg-card)'"
          onclick="selectFacility('${facility.施設ID}', '${facility.施設名}', ${facility.利用料金})">
          <div style="font-size: 15px; font-weight: 600; color: var(--text); margin-bottom: 8px;">${facility.施設名}</div>
          <div style="font-size: 13px; color: var(--text-muted); margin-bottom: 4px;">📍 ${facility.住所}</div>
          <div style="font-size: 13px; color: var(--text-muted); margin-bottom: 4px;">🕐 ${facility.営業開始時間} ～ ${facility.営業終了時間}</div>
          <div style="font-size: 13px; color: var(--text-muted); margin-bottom: 8px;">定員: ${facility.定員}名</div>
          <div style="font-size: 14px; font-weight: 600; color: var(--primary);">¥${facility.利用料金.toLocaleString()}</div>
          <div style="font-size: 12px; color: var(--text-muted); margin-top: 8px; padding-top: 8px; border-top: 1px solid var(--border);">
            ${facility.予約可能フラグ ? '✓ オンライン予約可能' : '予約受付中止'}
          </div>
        </div>
      `).join('');
    };

    searchInput.addEventListener('input', renderFacilities);
    categoryFilter.addEventListener('change', renderFacilities);
    renderFacilities();
  }

  // Load bookings
  async function loadBookings() {
    const bookings = await window.aivicApi.list(bookingsTableIndex);
    if (!bookings) return;

    const bookingsPanel = container.querySelector('#bookings-panel');
    const bookingsCount = container.querySelector('#bookings-count');
    bookingsCount.textContent = bookings.length;

    bookingsPanel.innerHTML = bookings.map(booking => `
      <div class="card" style="padding: 16px; border-radius: var(--radius-card); background: var(--bg-card); border: 1px solid var(--border);">
        <div style="font-size: 15px; font-weight: 600; color: var(--text); margin-bottom: 8px;">${booking.施設名}</div>
        <div style="font-size: 13px; color: var(--text-muted); margin-bottom: 4px;">📅 ${booking.予約日}</div>
        <div style="font-size: 13px; color: var(--text-muted); margin-bottom: 8px;">💰 ¥${booking.予約金額.toLocaleString()}</div>
        <div style="display: inline-block; padding: 4px 8px; background: var(--success-light); color: var(--success); border-radius: 3px; font-size: 12px; font-weight: 600; margin-bottom: 12px;">
          ${booking.予約状態}
        </div>
        <div style="display: flex; gap: 8px;">
          <button 
            class="edit-booking-btn"
            data-id="${booking.予約ID}"
            style="flex: 1; padding: 8px; background: transparent; border: 1px solid var(--border); border-radius: var(--radius-control); color: var(--text); font-size: 13px; cursor: pointer;"
          >
            変更
          </button>
          <button 
            class="cancel-booking-btn"
            data-id="${booking.予約ID}"
            style="flex: 1; padding: 8px; background: transparent; border: 1px solid var(--border); border-radius: var(--radius-control); color: #c62828; font-size: 13px; cursor: pointer;"
          >
            キャンセル
          </button>
        </div>
      </div>
    `).join('');
  }

  // Select facility
  window.selectFacility = function(facilityId, facilityName, price) {
    selectedFacilityId = facilityId;
    const dateInput = container.querySelector('[data-testid="facility-date-input"]');
    selectedDate = dateInput.value;

    if (!selectedDate) {
      alert('利用日を選択してください');
      return;
    }

    const timeSlotRadios = container.querySelectorAll('input[name="time-slot"]');
    selectedTimeSlot = Array.from(timeSlotRadios).find(r => r.checked)?.value;

    if (!selectedTimeSlot) {
      alert('時間帯を選択してください');
      return;
    }

    // Show action modal
    const actionModal = container.querySelector('#action-modal');
    const actionModalTitle = container.querySelector('#action-modal-title');
    const actionModalBody = container.querySelector('#action-modal-body');

    actionModalTitle.textContent = '予約方法を選択';
    actionModalBody.innerHTML = `
      <div style="margin-bottom: 16px;">
        <p style="margin: 0 0 8px 0; font-weight: 600;">${facilityName}</p>
        <p style="margin: 0 0 8px 0; color: var(--text-muted);">📅 ${selectedDate}</p>
        <p style="margin: 0; color: var(--text-muted);">💰 ¥${price.toLocaleString()}</p>
      </div>
      <div style="display: flex; flex-direction: column; gap: 8px;">
        <button 
          data-testid="book-button"
          style="padding: 12px; background: var(--primary); color: #fff; border: none; border-radius: var(--radius-control); font-weight: 600; cursor: pointer;"
          onmouseover="this.style.background='var(--primary-hover)'"
          onmouseout="this.style.background='var(--primary)'"
          onclick="confirmBooking('book')"
        >
          予約する
        </button>
        <button 
          data-testid="lottery-button"
          style="padding: 12px; background: transparent; border: 1px solid var(--border); border-radius: var(--radius-control); color: var(--text); font-weight: 600; cursor: pointer;"
          onclick="confirmBooking('lottery')"
        >
          抽選に申し込む
        </button>
      </div>
    `;
    actionModal.style.display = 'flex';
  };

  // Confirm booking/lottery
  window.confirmBooking = async function(action) {
    currentAction = action;
    const actionModal = container.querySelector('#action-modal');
    actionModal.style.display = 'none';

    // Save booking or lottery
    if (action === 'book') {
      const newBooking = {
        利用者ID: 'user-123',
        施設ID: selectedFacilityId,
        予約日: selectedDate,
        予約状態: '確定',
        決済状態: '未決済'
      };
      const saved = await window.aivicApi.save(bookingsTableIndex, newBooking);
      if (saved) {
        alert('予約が完了しました');
        await loadBookings();
      }
    } else if (action === 'lottery') {
      alert('抽選申込が完了しました');
    }
  };

  // Edit booking
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('edit-booking-btn')) {
      const bookingId = e.target.dataset.id;
      const reservationModal = container.querySelector('#reservation-modal');
      const modalContent = container.querySelector('#modal-content');
      modalContent.innerHTML = `<p>予約ID: ${bookingId}</p><p>変更内容を入力してください</p>`;
      reservationModal.style.display = 'flex';
    }
  });

  // Cancel booking
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('cancel-booking-btn')) {
      const bookingId = e.target.dataset.id;
      const cancelModal = container.querySelector('#cancel-modal');
      cancelModal.dataset.bookingId = bookingId;
      cancelModal.style.display = 'flex';
    }
  });

  // Confirm cancel
  container.querySelector('[data-testid="cancel-confirm-button"]').addEventListener('click', async () => {
    const cancelModal = container.querySelector('#cancel-modal');
    const bookingId = cancelModal.dataset.bookingId;
    const reason = container.querySelector('input[name="cancel-reason"]:checked')?.value;

    if (!reason) {
      alert('キャンセル理由を選択してください');
      return;
    }

    const cancelData = {
      予約ID: bookingId,
      キャンセル理由: reason,
      キャンセル日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(5, cancelData); // Cancel table index
    if (saved) {
      alert('予約がキャンセルされました');
      cancelModal.style.display = 'none';
      await loadBookings();
    }
  });

  // Close modals on backdrop click
  const modals = container.querySelectorAll('.modal-overlay');
  modals.forEach(modal => {
    modal.addEventListener('click', (e) => {
      if (e.target === modal) {
        modal.style.display = 'none';
      }
    });
  });

  // Attach event listeners
  function attachEventListeners() {
    const searchBtn = container.querySelector('[data-testid="search-button"]');
    searchBtn.addEventListener('click', () => {
      // Search is already handled by input event listeners
    });
  }

  init();
}

function(container, apiUrl, tables) {
  const reservationData = {};
  const paymentData = {};
  let currentReservationId = null;

  // DOM Elements
  const facilityNameEl = container.querySelector('[data-testid="facility-name"]');
  const reservationDateEl = container.querySelector('[data-testid="reservation-date"]');
  const reservationTimeEl = container.querySelector('[data-testid="reservation-time"]');
  const reservationPeopleEl = container.querySelector('[data-testid="reservation-people"]');
  const totalAmountEl = container.querySelector('[data-testid="total-amount"]');

  const paymentMethodRadios = container.querySelectorAll('input[name="payment-method"]');
  const creditCardForm = container.querySelector('#credit-card-form');
  const bankTransferInfo = container.querySelector('#bank-transfer-info');
  const convenienceForm = container.querySelector('#convenience-form');

  const processingIndicator = container.querySelector('#processing-indicator');
  const statusMessage = container.querySelector('#status-message');
  const downloadButton = container.querySelector('#download-button');
  const backLink = container.querySelector('#back-link');

  const executePaymentButton = container.querySelector('#execute-payment-button');
  const cancelButton = container.querySelector('#cancel-button');

  // Payment method form visibility toggle
  function updatePaymentFormVisibility(method) {
    creditCardForm.style.display = method === 'credit-card' ? 'block' : 'none';
    bankTransferInfo.style.display = method === 'bank-transfer' ? 'block' : 'none';
    convenienceForm.style.display = method === 'convenience' ? 'block' : 'none';
  }

  paymentMethodRadios.forEach(radio => {
    radio.addEventListener('change', (e) => {
      updatePaymentFormVisibility(e.target.value);
    });
  });

  // Initialize with first payment method visible
  updatePaymentFormVisibility('credit-card');

  // Load reservation data from URL params or session
  async function loadReservationData() {
    try {
      // Get reservation ID from URL params (e.g., ?reservationId=xxx)
      const params = new URLSearchParams(window.location.search);
      currentReservationId = params.get('reservationId');

      if (!currentReservationId && tables && tables[0]) {
        // Fallback: use first reservation from table
        const reservations = await window.aivicApi.list(0); // Assuming index 0 is reservations
        if (reservations && reservations.length > 0) {
          currentReservationId = reservations[0].id;
        }
      }

      if (!currentReservationId) {
        showError('予約情報が見つかりません');
        return;
      }

      // Fetch full reservation details
      const reservation = await window.aivicApi.list(0); // Get all reservations
      const currentRes = reservation.find(r => r.id === currentReservationId);

      if (!currentRes) {
        showError('予約情報が見つかりません');
        return;
      }

      // Fetch facility info
      const facilities = await window.aivicApi.list(1); // Assuming index 1 is facilities
      const facility = facilities.find(f => f.id === currentRes.施設ID);

      if (!facility) {
        showError('施設情報が見つかりません');
        return;
      }

      // Populate reservation data
      reservationData.id = currentRes.id;
      reservationData.facilityId = facility.id;
      reservationData.facilityName = facility.施設名;
      reservationData.reservationDate = currentRes.予約日;
      reservationData.startTime = currentRes.開始時刻 || '09:00';
      reservationData.endTime = currentRes.終了時刻 || '10:00';
      reservationData.people = currentRes.人数 || 1;
      reservationData.amount = currentRes.予約金額 || facility.利用料金;

      // Display reservation info
      facilityNameEl.textContent = reservationData.facilityName;
      reservationDateEl.textContent = new Date(reservationData.reservationDate).toLocaleDateString('ja-JP');
      reservationTimeEl.textContent = `${reservationData.startTime}～${reservationData.endTime}`;
      reservationPeopleEl.textContent = `${reservationData.people}名`;
      totalAmountEl.textContent = `¥${reservationData.amount.toLocaleString()}`;

    } catch (error) {
      console.error('Failed to load reservation data:', error);
      showError('予約情報の読み込みに失敗しました');
    }
  }

  // Execute payment
  executePaymentButton.addEventListener('click', async () => {
    const selectedMethod = container.querySelector('input[name="payment-method"]:checked').value;

    // Validate payment method specific fields
    if (selectedMethod === 'credit-card') {
      const cardNumber = container.querySelector('[data-testid="card-number"]').value.trim();
      const cardExpiry = container.querySelector('[data-testid="card-expiry"]').value.trim();
      const cardCvv = container.querySelector('[data-testid="card-cvv"]').value.trim();

      if (!cardNumber || !cardExpiry || !cardCvv) {
        showError('カード情報をすべて入力してください');
        return;
      }
    } else if (selectedMethod === 'convenience') {
      const convenience = container.querySelector('[data-testid="convenience-store-select"]').value;
      if (!convenience) {
        showError('コンビニを選択してください');
        return;
      }
    }

    // Show processing indicator
    processingIndicator.style.display = 'block';
    executePaymentButton.disabled = true;
    cancelButton.disabled = true;
    statusMessage.style.display = 'none';

    try {
      // Simulate payment processing (2 seconds)
      await new Promise(resolve => setTimeout(resolve, 2000));

      // Create payment record
      const paymentRecord = {
        予約ID: currentReservationId,
        利用者ID: 'user-' + Date.now(), // Placeholder
        決済金額: reservationData.amount,
        決済方法: selectedMethod,
        決済ステータス: '決済済',
        決済日時: new Date().toISOString(),
        トランザクションID: 'TXN-' + Date.now(),
        備考: ''
      };

      // Save payment record (assuming index 2 is payments table)
      const saved = await window.aivicApi.save(2, paymentRecord);

      if (!saved) {
        throw new Error('Payment save failed');
      }

      // Update reservation status
      const updatedReservation = {
        予約状態: '確定',
        決済状態: '決済済'
      };
      await window.aivicApi.update(0, currentReservationId, updatedReservation);

      // Show success message
      processingIndicator.style.display = 'none';
      showSuccess('決済が完了しました。予約が確定しました。');

      // Show download button and back link
      downloadButton.style.display = 'block';
      backLink.style.display = 'block';
      executePaymentButton.style.display = 'none';
      cancelButton.style.display = 'none';

    } catch (error) {
      console.error('Payment execution failed:', error);
      processingIndicator.style.display = 'none';
      showError('決済処理に失敗しました。もう一度お試しください。');
      executePaymentButton.disabled = false;
      cancelButton.disabled = false;
    }
  });

  // Cancel button
  cancelButton.addEventListener('click', () => {
    if (confirm('決済をキャンセルしますか？')) {
      window.history.back();
    }
  });

  // Download button
  downloadButton.addEventListener('click', () => {
    const csv = generateConfirmationCSV();
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `予約確認書_${currentReservationId}.csv`;
    link.click();
  });

  // Back link
  backLink.addEventListener('click', () => {
    window.location.href = '/panels/reservations-list.html';
  });

  // Helper functions
  function showError(message) {
    statusMessage.textContent = message;
    statusMessage.style.display = 'block';
    statusMessage.style.background = 'var(--error-light)';
    statusMessage.style.color = 'var(--error)';
    statusMessage.style.borderLeft = '3px solid var(--error)';
  }

  function showSuccess(message) {
    statusMessage.textContent = message;
    statusMessage.style.display = 'block';
    statusMessage.style.background = 'var(--success-light)';
    statusMessage.style.color = 'var(--success)';
    statusMessage.style.borderLeft = '3px solid var(--success)';
  }

  function generateConfirmationCSV() {
    const bom = '\uFEFF';
    const headers = ['項目', '内容'];
    const rows = [
      ['予約ID', currentReservationId],
      ['施設名', reservationData.facilityName],
      ['利用日', new Date(reservationData.reservationDate).toLocaleDateString('ja-JP')],
      ['利用時間', `${reservationData.startTime}～${reservationData.endTime}`],
      ['利用人数', `${reservationData.people}名`],
      ['利用料金', `¥${reservationData.amount.toLocaleString()}`],
      ['決済日時', new Date().toLocaleString('ja-JP')],
      ['決済方法', container.querySelector('input[name="payment-method"]:checked').value]
    ];

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.map(cell => `"${cell}"`).join(','))
    ].join('\n');

    return bom + csvContent;
  }

  // Initialize
  loadReservationData();
}
